package cn.iocoder.yudao.module.zsjos.dal.mysql.studentops;
import cn.iocoder.yudao.framework.mybatis.core.mapper.BaseMapperX; import cn.iocoder.yudao.module.zsjos.dal.dataobject.studentops.GraduationApplicationDO; import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import org.apache.ibatis.annotations.Mapper; import java.util.List;
@Mapper public interface GraduationApplicationMapper extends BaseMapperX<GraduationApplicationDO> { default GraduationApplicationDO selectByProcessId(String pid){return selectOne(new LambdaQueryWrapper<GraduationApplicationDO>().eq(GraduationApplicationDO::getProcessInstanceId,pid));} default List<GraduationApplicationDO> selectByParticipant(Long uid){return selectList(new LambdaQueryWrapper<GraduationApplicationDO>().and(q->q.eq(GraduationApplicationDO::getPlannerUserId,uid).or().eq(GraduationApplicationDO::getReviewerUserId,uid)).orderByDesc(GraduationApplicationDO::getUpdateTime).orderByDesc(GraduationApplicationDO::getId));} default List<GraduationApplicationDO> selectByStudent(Long studentPersonId){return selectList(new LambdaQueryWrapper<GraduationApplicationDO>().eq(GraduationApplicationDO::getStudentPersonId,studentPersonId).orderByDesc(GraduationApplicationDO::getUpdateTime).orderByDesc(GraduationApplicationDO::getId).last("LIMIT 100"));} }
